int readcount = 0;
semaphore rmutex = 1;   // 保护 readcount
semaphore wmutex = 1;   // 写者互斥，兼读/写互斥

reader() {
    while (1) {
        P(rmutex);
        if (readcount == 0)
            P(wmutex);       // 第一个读者锁住写者
        readcount++;
        V(rmutex);
        // ---- 读数据 ----
        P(rmutex);
        readcount--;
        if (readcount == 0)
            V(wmutex);       // 最后一个读者放行写者
        V(rmutex);
    }
}

writer() {
    while (1) {
        P(wmutex);
        // ---- 写数据 ----
        V(wmutex);
    }
}
